window.SUBJECTS['office-mgmt'] = {
  title: 'Office Management',
  type: 'mcq',
  units: [],
  mcqs: [{"u":"Unit 1","t":"Meaning of Office","n":1,"q":"An office is best described as","o":["the storage centre where finished goods are kept before dispatch","the sales centre where goods are displayed and sold to customers","the administrative centre where information is received, processed, recorded, stored and communicated","the production centre where raw materials are converted into finished goods"],"a":2,"e":"The office is the administrative centre where information is received, processed, recorded, stored and communicated.","g":1,"w":["Keeping finished goods is the warehouse's job.","Displaying and selling goods is the sales outlet's job.","","Converting raw materials into goods is the factory's job."]},{"u":"Unit 1","t":"Meaning of Office","n":2,"q":"According to George R. Terry, an office is a place where","o":["raw materials are converted into finished goods for sale to customers","goods are purchased in bulk and sold to retailers at a margin","records are prepared, stored and communicated to support business operations","cash is collected from customers and deposited in the bank daily"],"a":2,"e":"Terry sees the office as the place where records are prepared, stored and communicated to support operations.","g":1,"w":["That describes a factory.","That describes a wholesaler.","","Cash collection is only one cashier task, not the definition of an office."]},{"u":"Unit 1","t":"Meaning of Office","n":3,"q":"The office is often called the","o":["heart of the factory","engine room of production","nerve centre of an organisation","backbone of the market"],"a":2,"e":"Nearly every department sends and receives information through the office, so it is the nerve centre.","g":1,"w":["A factory has its own heart - production.","Production's engine room is the plant.","","'Backbone of the market' describes distribution, not the office."]},{"u":"Unit 1","t":"Meaning of Office","n":4,"q":"Which is NOT a characteristic of an office?","o":["Coordination centre","Information centre","Manufacturing centre","Record centre"],"a":2,"e":"An office handles information; manufacturing is done in a factory.","g":1,"w":["Coordination centre is a real office role.","Information centre is a real office role.","","Record centre is a real office role."]},{"u":"Unit 1","t":"Meaning of Office","n":5,"q":"A modern office may also be a","o":["virtual or digital workplace","only a godown","only a factory shed","only a physical room"],"a":0,"e":"Modern offices can be virtual, so an office need not be a physical place.","g":1,"w":["","A godown is a storage place.","A factory shed is a production place.","It is not limited to a physical room."]},{"u":"Unit 1","t":"Importance of Office","n":6,"q":"Which statement about the importance of office is correct?","o":["It is needed only in manufacturing firms and not in service firms","It has no role in the decisions taken by the management","It only stores raw materials and finished goods of the firm","It facilitates communication and provides information to management"],"a":3,"e":"The office provides information and communication that management needs.","g":1,"w":["Service firms need offices too.","Offices support decisions with information.","Storing materials is a godown job.",""]},{"u":"Unit 1","t":"Office Management","n":7,"q":"Office management means","o":["planning, organising, directing and controlling office activities for efficient and economical work","preparing the annual accounts and filing the income tax returns","buying, selling and distributing goods to earn the maximum profit","recruiting, training and dismissing employees of the organisation"],"a":0,"e":"Office management applies planning, organising, directing and controlling to office work.","g":1,"w":["","Accounts and tax filing is accounting.","Buying and selling is trading.","Recruiting and dismissing is HR."]},{"u":"Unit 1","t":"Office Management","n":8,"q":"Which is an objective of office management?","o":["To keep the records scattered in different departments","To delay the flow of information to the managers","To ensure smooth office operations","To increase the operating cost of the office every year"],"a":2,"e":"An objective is to make office operations run smoothly.","g":1,"w":["It should keep records organised, not scattered.","It should speed, not delay, information.","","Management aims to reduce, not raise, cost."]},{"u":"Unit 1","t":"Office Management","n":9,"q":"Office management is considered both an","o":["a service and a product sold in the market","a theory and a hobby without any practical use","a profession and a trade protected by law","art and a science"],"a":3,"e":"It needs skill and leadership (art) and also principles and systematic methods (science).","g":1,"w":["Service and product do not describe its nature.","It has practical use.","A profession and trade do not describe its nature.",""]},{"u":"Unit 1","t":"Office Management","n":10,"q":"Resolving a conflict between two employees professionally shows office management as","o":["a rule","an art","a science","a machine"],"a":1,"e":"Handling people takes tact and leadership, which is an art.","g":1,"w":["A rule cannot handle the human side.","","Science uses fixed procedures and measurement.","A conflict is not solved by a machine."]},{"u":"Unit 1","t":"Office Management","n":11,"q":"Preparing salary sheets using software shows office management as","o":["luck","a science","an art","a hobby"],"a":1,"e":"Software-based payroll follows fixed systematic procedures, so it is science.","g":1,"w":["It is not luck.","","Art needs personal skill and creativity.","It is a job, not a hobby."]},{"u":"Unit 1","t":"Office Management","n":12,"q":"Motivating employees is an example of","o":["filing","art","science","automation"],"a":1,"e":"Motivating depends on leadership skill, so it is an art.","g":1,"w":["Filing is storage of documents.","","Science is systematic procedure.","Automation uses machines."]},{"u":"Unit 1","t":"Functions of Office","n":13,"q":"Which of the following is a BASIC function of an office?","o":["Buying raw materials, hiring labour and fixing the selling price","Designing, manufacturing, packing and dispatching finished products","Receiving, recording, processing, storing and supplying information","Advertising, selling and collecting payments from customers"],"a":2,"e":"Basic functions are receiving, recording, processing, storing and supplying information.","g":1,"w":["Buying and pricing are trading decisions.","Designing and manufacturing are production.","","Advertising and selling are marketing."]},{"u":"Unit 1","t":"Functions of Office","n":14,"q":"Converting raw data like 100 complaints into a classified report is","o":["destroying information","storing information","receiving information","processing information"],"a":3,"e":"Turning raw complaints into a classified report is processing information.","g":1,"w":["Destroying removes data.","Storing is keeping data.","Receiving is taking in data.",""]},{"u":"Unit 1","t":"Functions of Office","n":15,"q":"Which is an ADMINISTRATIVE function of the office?","o":["Planning and supervising office work","Receiving and recording the information that comes to the office","Storing the information in files and in computer databases","Processing the raw data into useful reports for the managers"],"a":0,"e":"Planning and supervising are management-type administrative functions.","g":1,"w":["","Receiving and recording is a basic function.","Storing data is a basic function.","Processing data is a basic function."]},{"u":"Unit 1","t":"Office Organisation","n":16,"q":"Office organisation means","o":["the buying and arrangement of furniture and equipment in the office","the systematic arrangement of people, resources, duties and procedures to achieve objectives efficiently","the planning of the annual budget and the sources of finance","the process of recruiting and selecting staff for the office"],"a":1,"e":"Office organisation arranges people, duties and procedures to reach objectives.","g":1,"w":["Buying furniture is accommodation.","","Budgeting is finance.","Recruiting is HR."]},{"u":"Unit 1","t":"Office Organisation","n":17,"q":"Which principle states that an employee should receive instructions from only one superior?","o":["Unity of command","Division of work","Flexibility","Coordination"],"a":0,"e":"Unity of command: one employee takes orders from one superior.","g":1,"w":["","Division of work splits tasks.","Flexibility is adjusting to change.","Coordination links activities."]},{"u":"Unit 1","t":"Office Organisation","n":18,"q":"Dividing work according to specialisation is the principle of","o":["unity of command","division of work","simplicity","flexibility"],"a":1,"e":"Dividing work by specialisation is division of work.","g":1,"w":["Unity of command is one boss.","","Simplicity is a clear structure.","Flexibility is adaptability."]},{"u":"Unit 1","t":"Office Organisation","n":19,"q":"'Authority and responsibility should go hand in hand' is a principle of","o":["office organisation","marketing mix","recruitment","financial leverage"],"a":0,"e":"Authority with responsibility is one of the principles of office organisation.","g":1,"w":["","Marketing mix is 4Ps.","Recruitment is HR.","Financial leverage is a finance term."]},{"u":"Unit 1","t":"Office Manager","n":20,"q":"An office manager is the link between","o":["customers and suppliers","banks and borrowers","management and office staff","buyers and sellers"],"a":2,"e":"The office manager links top management and the office staff.","g":1,"w":["Customers-suppliers is trade.","Banks-borrowers is finance.","","Buyers-sellers is market."]},{"u":"Unit 1","t":"Office Manager","n":21,"q":"Which is a function of the office manager?","o":["Advertising on social media only","Staff supervision and record management","Manufacturing goods","Auditing the company's accounts independently"],"a":1,"e":"Supervising staff and managing records are office manager's duties.","g":1,"w":["Advertising is marketing's job.","","Manufacturing is the plant's job.","Independent audit is an auditor's job."]},{"u":"Unit 1","t":"Office Support Services","n":22,"q":"Reception and mail service are examples of","o":["marketing research","office support services","production activities","financial leverage"],"a":1,"e":"Reception and mail help the main work, so they are support services.","g":1,"w":["Marketing research studies markets.","","Production makes goods.","Financial leverage is a finance term."]},{"u":"Unit 1","t":"Modern Office","n":23,"q":"Which is a characteristic of a modern office?","o":["Slow communication through postal letters and personal messengers","Extensive use of technology and digital communication","Complete reliance on paper files and physical filing cabinets","Dependence on typewriters and handwritten registers for all records"],"a":1,"e":"Modern offices use technology and digital communication.","g":1,"w":["Postal and messengers are slow old methods.","","Paper filing alone is old.","Typewriters and registers are old methods."]},{"u":"Unit 1","t":"Modern Office","n":24,"q":"Instead of manually entering attendance, a biometric system generating an attendance report is an example of","o":["manual filing","typing","automation","dictation"],"a":2,"e":"A biometric attendance report is an automated routine task.","g":1,"w":["Manual filing is by hand.","Typing is by hand.","","Dictation is spoken for typing."]},{"u":"Unit 1","t":"Paperless Office","n":25,"q":"A paperless office means","o":["no paper of any kind is ever used or stored in the office","all documents are handwritten and kept in locked steel cabinets","documents are primarily created, stored and communicated electronically, with minimum dependence on paper","employees work only from home and never visit the office"],"a":2,"e":"Paperless means documents are mainly electronic, not that paper vanishes totally.","g":1,"w":["Zero paper is not required.","Handwritten files are the opposite.","","Working from home is virtual office."]},{"u":"Unit 1","t":"Paperless Office","n":26,"q":"Which is an advantage of a paperless office?","o":["Cannot be shared","Higher paper cost","More storage space needed","Faster retrieval of records"],"a":3,"e":"Electronic records are found faster.","g":1,"w":["Electronic files are easy to share.","Paperless reduces paper cost.","It needs less storage space.",""]},{"u":"Unit 1","t":"Paperless Office","n":27,"q":"Which is a limitation of a paperless office?","o":["Easy sharing","Saves storage space","Cybersecurity risk","Faster retrieval"],"a":2,"e":"Digital records are exposed to hacking and cyber-attacks.","g":1,"w":["Easy sharing is an advantage.","Saving space is an advantage.","","Faster retrieval is an advantage."]},{"u":"Unit 1","t":"Virtual Office","n":28,"q":"A virtual office is one where employees","o":["all employees are seated together in a single large open hall","work without being permanently located in a traditional physical office","every employee has a separate cabin with fixed working hours","work is done only on the factory floor under direct supervision"],"a":1,"e":"In a virtual office employees work without being permanently at a physical office.","g":1,"w":["All together in one hall is an open office.","","Separate cabins is a closed office.","Factory floor work is production."]},{"u":"Unit 1","t":"Virtual Office","n":29,"q":"Which is a disadvantage of a virtual office?","o":["Higher office rent","Reduced flexibility","Limited face-to-face interaction","Smaller talent pool"],"a":2,"e":"Virtual work reduces face-to-face contact.","g":1,"w":["Rent is lower, not higher.","Flexibility is greater, not less.","","The talent pool is wider, not smaller."]},{"u":"Unit 1","t":"Virtual Office","n":30,"q":"Which is an advantage of a virtual office?","o":["Stronger team bonding through daily personal interaction","Lower office rent and wider talent pool","Better face-to-face supervision of all the employees at one place","Higher rent and larger infrastructure cost for the organisation"],"a":1,"e":"A virtual office cuts rent and widens the talent pool.","g":1,"w":["Daily personal interaction is a physical-office strength.","","Face-to-face supervision is a physical-office strength.","Virtual cuts infrastructure cost."]},{"u":"Unit 1","t":"Virtual Office","n":31,"q":"GitLab is an example of an organisation that moved to an","o":["all-factory model","single-cabin office","cubicle only","all-remote workplace"],"a":3,"e":"GitLab operates fully remote - an all-remote workplace.","g":1,"w":["It is not factory based.","It has no single-cabin office.","It is not a cubicle office.",""]},{"u":"Unit 1","t":"Virtual Office","n":32,"q":"A hybrid office combines","o":["only private cabins and cubicles for all the employees","only virtual meetings with no physical workspace at all","physical office work and remote work","paper records and typewriters with the filing cabinets"],"a":2,"e":"A hybrid office mixes work in the office and from home.","g":1,"w":["Cabins and cubicles are physical only.","Only virtual leaves out the office.","","Paper records and typewriters are old tools."]},{"u":"Unit 1","t":"Front & Back Office","n":33,"q":"The front office is the department that","o":["handles internal accounting and payroll without meeting any customer","processes data and stores records for the organisation's use only","directly interacts with customers, visitors and other outsiders","manages information technology support for the other departments"],"a":2,"e":"The front office meets customers and visitors directly.","g":1,"w":["Internal accounting is back office.","Data storing is back office.","","IT support is back office."]},{"u":"Unit 1","t":"Front & Back Office","n":34,"q":"Accounts, HR, IT support and administration are examples of","o":["front office","back office","middle office","virtual office"],"a":1,"e":"Accounts, HR, IT and admin do not deal with customers - back office.","g":1,"w":["Front office faces customers.","","Middle office handles risk and compliance.","Virtual office is a work model."]},{"u":"Unit 1","t":"Front & Back Office","n":35,"q":"The risk management and compliance teams are examples of the","o":["middle office","front office","private office","back office"],"a":0,"e":"Risk management and compliance sit between front and back, the middle office.","g":1,"w":["","Front office meets customers.","Private office is a room type.","Back office is routine support."]},{"u":"Unit 1","t":"Front & Back Office","n":36,"q":"In a hotel, the receptionist who welcomes you belongs to the","o":["back office","front office","virtual office","sublet office"],"a":1,"e":"A receptionist who welcomes guests is front office.","g":1,"w":["Back office does not meet guests.","","Virtual office is remote work.","Sublet office is rented space."]},{"u":"Unit 1","t":"Front & Back Office","n":37,"q":"An electronic office (E-Office) mainly aims to","o":["reduce the number of customers served by the firm","increase the paperwork and slow down the operations of the firm","reduce paperwork and speed up operations","avoid the use of computers and software in office work"],"a":2,"e":"An e-office cuts paperwork and speeds work with digital tools.","g":1,"w":["It aims to serve customers better.","It reduces paperwork.","","It uses computers."]},{"u":"Unit 1","t":"Office Layout","n":38,"q":"Office layout means","o":["the legal registration of the office with the registrar of companies","the list of rules and policies to be followed by office employees","the colour scheme and decoration chosen for the reception area","the planned arrangement of departments, furniture, equipment and employees within the office"],"a":3,"e":"Layout is the planned arrangement of departments, furniture, equipment and people.","g":1,"w":["Registration is legal.","Rules are an office manual.","Colour scheme is decoration.",""]},{"u":"Unit 1","t":"Office Layout","n":39,"q":"Which is an objective of a good office layout?","o":["Maximum movement of employees between the departments","Smooth flow of work and maximum space utilisation","Large empty space in the office for future use only","Poor supervision and weak communication among the staff"],"a":1,"e":"A good layout smooths work flow and uses space well.","g":1,"w":["Excess movement wastes time.","","Empty space wastes rent.","Poor supervision is a fault."]},{"u":"Unit 1","t":"Office Layout","n":40,"q":"A layout where employees work together in a large area without permanent walls is the","o":["closed office layout","cubicle layout","open office layout","private office layout"],"a":2,"e":"A common area without permanent walls is an open layout.","g":1,"w":["Closed layout uses rooms.","Cubicle layout uses partitions.","","Private layout uses cabins."]},{"u":"Unit 1","t":"Office Layout","n":41,"q":"A major disadvantage of the open office layout is","o":["noise and lack of privacy","high cost of cabins","poor communication","high rent only"],"a":0,"e":"Open spaces cause noise and little privacy.","g":1,"w":["","Open layouts avoid the cost of cabins.","Communication is easy in open layouts.","Open layouts usually save rent."]},{"u":"Unit 1","t":"Office Layout","n":42,"q":"Separate rooms or cabins giving privacy and confidentiality describe the","o":["modular layout with movable furniture and workstations","cubicle layout with low partitions between the workstations","closed (private) office layout","open office layout in which all work in a common hall"],"a":2,"e":"Separate rooms or cabins give privacy: closed layout.","g":1,"w":["Modular layout uses movable furniture.","Cubicle layout uses low partitions.","","Open layout is a common hall."]},{"u":"Unit 1","t":"Office Layout","n":43,"q":"Partitioned semi-private workstations are used in the","o":["private cabins","cubicle layout","virtual office","open layout"],"a":1,"e":"Semi-private partitioned workstations are cubicles.","g":1,"w":["Private cabins are full rooms.","","Virtual offices have no room.","Open layout has no partitions."]},{"u":"Unit 1","t":"Office Layout","n":44,"q":"A layout with movable furniture that can be rearranged to meet changing needs is the","o":["modular / flexible layout","traditional layout","cubicle layout","closed layout"],"a":0,"e":"Movable furniture that can be rearranged is modular or flexible layout.","g":1,"w":["","Traditional layout is fixed.","Cubicle layout has fixed partitions.","Closed layout has fixed rooms."]},{"u":"Unit 1","t":"Office Layout","n":45,"q":"A layout combining open spaces, private cabins and meeting rooms is the","o":["open layout","closed layout","hybrid layout","cubicle layout"],"a":2,"e":"Open space plus cabins plus meeting rooms is hybrid layout.","g":1,"w":["Open is only open space.","Closed is only cabins.","","Cubicle is only partitions."]},{"u":"Unit 1","t":"Types of Offices","n":46,"q":"A bank or lawyer's office with separate cabins and formal atmosphere is a","o":["coworking office","sublet office","creative office","traditional office"],"a":3,"e":"Banks and lawyers use formal, private cabins: traditional office.","g":1,"w":["Coworking shares space.","Sublet offices are rented from tenants.","Creative offices are open.",""]},{"u":"Unit 1","t":"Types of Offices","n":47,"q":"An office with open seating and few walls such as in Google is a","o":["traditional office","creative office","executive suite","sublet office"],"a":1,"e":"Open seating with few walls is a creative office (e.g. Google).","g":1,"w":["Traditional offices have cabins.","","Executive suite is ready-furnished space.","Sublet is rented space."]},{"u":"Unit 1","t":"Types of Offices","n":48,"q":"An office where different companies work in the same space and rent only the desks they need is a","o":["contiguous office","coworking office","private office","enterprise suite"],"a":1,"e":"Coworking: different firms share space and rent desks.","g":1,"w":["Contiguous means adjoining floors.","","Private office is for one firm.","Enterprise suite is a large leased space."]},{"u":"Unit 1","t":"Types of Offices","n":49,"q":"A ready-to-move-in office with furniture, internet and phone already installed is an","o":["contiguous office","sublet office","executive suite","enterprise suite"],"a":2,"e":"An executive suite is a ready-to-use furnished office.","g":1,"w":["Contiguous means adjoining.","Sublet is sub-leased.","","Enterprise suite is a larger leased block."]},{"u":"Unit 1","t":"Types of Offices","n":50,"q":"An office rented from another tenant, usually short-term and cheaper, is a","o":["contiguous office","sublet office","private office","creative office"],"a":1,"e":"A sublet office is rented from another tenant, short term and cheaper.","g":1,"w":["Contiguous means adjoining.","","Private office is one's own.","Creative is a style."]},{"u":"Unit 1","t":"Office Accommodation","n":51,"q":"Which factor determines the size of an office building?","o":["Name of the architect and the year of construction","Distance of the office from the owner's residence","Nature of business, number of employees and future expansion","Colour of the walls and the brand of furniture selected"],"a":2,"e":"Size depends on the type of business, staff and future growth.","g":1,"w":["The architect's name is irrelevant.","Distance from the owner's home is irrelevant.","","Colour and furniture brand do not decide size."]},{"u":"Unit 1","t":"Office Accommodation","n":52,"q":"Fire extinguishers, emergency exits and first-aid boxes are","o":["filing methods","security measures","safety measures","layout types"],"a":2,"e":"Fire extinguishers, exits and first-aid protect from accidents: safety.","g":1,"w":["Filing methods arrange documents.","Security guards against theft.","","Layout types are plans."]},{"u":"Unit 1","t":"Office Accommodation","n":53,"q":"CCTV cameras, ID cards and biometric attendance are","o":["indexing methods","security measures","safety measures only","etiquette rules"],"a":1,"e":"CCTV, ID cards and biometrics guard against theft and intruders: security.","g":1,"w":["Indexing arranges records.","","Safety is about accidents.","Etiquette is behaviour."]},{"u":"Unit 1","t":"Office Environment","n":54,"q":"Lighting, ventilation, temperature and noise are part of the","o":["technological environment only","social environment only","physical environment","psychological environment"],"a":2,"e":"Light, air, temperature and noise form the physical environment.","g":1,"w":["Technological is machines and software.","Social is relationships.","","Psychological is mental."]},{"u":"Unit 1","t":"Office Environment","n":55,"q":"Stress, motivation, respect and recognition belong to the","o":["physical environment","legal environment","technological environment","psychological environment"],"a":3,"e":"Stress, motivation and recognition are mental/emotional: psychological environment.","g":1,"w":["Physical is light, air, noise.","Legal is laws.","Technological is tools.",""]},{"u":"Unit 1","t":"Office Systems","n":56,"q":"Step-by-step methods followed for performing office tasks are","o":["office procedures","office manuals only","office furniture","office layouts"],"a":0,"e":"Step-by-step methods for tasks are office procedures.","g":1,"w":["","A manual records procedures but is not the procedure itself.","Furniture is equipment.","Layouts are arrangements."]},{"u":"Unit 1","t":"Office Manual","n":57,"q":"A written document containing office policies, procedures, rules and guidelines is the","o":["office index","office layout","circular only","office manual"],"a":3,"e":"An office manual is the written book of policies and procedures.","g":1,"w":["Index is a finding guide.","Layout is a plan.","Circular is a notice.",""]},{"u":"Unit 1","t":"Office Manual","n":58,"q":"An office manual helps in","o":["employee training and standardisation of work","removing the need for employee communication and meetings","reducing the need for any supervision of the employees","increasing confusion and uncertainty about office policies and rules"],"a":0,"e":"A manual trains staff and standardises work.","g":1,"w":["","It supports communication.","It does not remove supervision.","It reduces confusion."]},{"u":"Unit 1","t":"Workplace Ethics","n":59,"q":"Which is a principle of workplace ethics?","o":["Conflict of interest","Dishonesty","Gossip","Confidentiality"],"a":3,"e":"Confidentiality is an ethical principle.","g":1,"w":["Conflict of interest should be avoided.","Dishonesty is unethical.","Gossip is unethical.",""]},{"u":"Unit 1","t":"Workplace Ethics","n":60,"q":"An employee who rejects a supplier's gift offered in exchange for approving a purchase order is following","o":["marketing strategy","cost cutting","workplace ethics","automation"],"a":2,"e":"Refusing a bribe is workplace ethics.","g":1,"w":["Marketing strategy is promotion.","Cost cutting is saving.","","Automation is technology."]},{"u":"Unit 1","t":"Office Machines","n":61,"q":"A machine used for securely destroying confidential documents is a","o":["scanner","shredder","laminator","projector"],"a":1,"e":"A shredder cuts documents into pieces to protect secrets.","g":1,"w":["A scanner digitises.","","A laminator seals paper in plastic.","A projector shows slides."]},{"u":"Unit 1","t":"Office Machines","n":62,"q":"A scanner is used to","o":["convert physical documents into digital form","destroy confidential documents securely before disposal","bind several documents together using a plastic coil","display presentations on a large screen to an audience"],"a":0,"e":"A scanner makes digital copies of paper documents.","g":1,"w":["","Shredding destroys.","Binding is another machine.","Projectors display."]},{"u":"Unit 1","t":"Office Machines","n":63,"q":"A biometric device is used for","o":["attendance and access control","photocopying and printing documents in large numbers","destroying confidential papers in a secure manner","binding and lamination of important office documents"],"a":0,"e":"Biometric devices read fingerprints for attendance and access.","g":1,"w":["","Photocopying is another machine.","Shredding is another machine.","Binding is another machine."]},{"u":"Unit 1","t":"Office Machines","n":64,"q":"Which is a factor to consider before purchasing office equipment?","o":["Colour of the vendor's logo only","Cost, quality, maintenance and warranty","Number of vendor's employees","Distance of vendor's home"],"a":1,"e":"Cost, quality, maintenance and warranty guide equipment purchase.","g":1,"w":["Logo colour is irrelevant.","","Vendor's staff count is irrelevant.","Vendor's home distance is irrelevant."]},{"u":"Unit 1","t":"Filing","n":65,"q":"Filing is","o":["the destruction of old and unwanted documents to save space","the systematic arrangement and storage of documents so they can be easily traced and retrieved","the typing and dispatch of letters to customers and suppliers","the process of dictating notes to a typist or secretary"],"a":1,"e":"Filing arranges and stores documents so they can be traced quickly.","g":1,"w":["Destroying is disposal.","","Typing and dispatch are correspondence.","Dictation is a typing task."]},{"u":"Unit 1","t":"Filing","n":66,"q":"Which is an objective of filing?","o":["Easy retrieval and safe custody","Delaying work","Destroying evidence","Increasing confusion"],"a":0,"e":"Filing aims for easy retrieval and safe keeping.","g":1,"w":["","Delay is a fault.","Destroying evidence is wrong.","Confusion is a fault."]},{"u":"Unit 1","t":"Filing","n":67,"q":"Which is an essential of a good filing system?","o":["Simple, economical, flexible and safe","Complicated, costly, rigid and unsafe for confidential papers","Based on a code that only the filing clerk can understand","Accessible only to the manager and no one else in the office"],"a":0,"e":"A good system is simple, economical, flexible and safe.","g":1,"w":["","Complicated and unsafe is a fault.","A secret code makes retrieval impossible for others.","Access only for the manager makes work slow."]},{"u":"Unit 1","t":"Filing","n":68,"q":"In centralised filing, documents of all departments are kept in","o":["one central filing department","employees' homes","bank lockers","each department separately"],"a":0,"e":"Centralised filing keeps all documents in one department.","g":1,"w":["","Employees' homes are unsafe.","Bank lockers are for valuables.","Each department separately is decentralised."]},{"u":"Unit 1","t":"Filing","n":69,"q":"A disadvantage of decentralised filing is","o":["duplication and different filing standards","uniform standards of filing followed in all the departments","lower cost because of the sharing of staff and equipment","better control of all records by a single central department"],"a":0,"e":"Decentralised filing causes duplication and unequal standards.","g":1,"w":["","Uniform standards belong to central filing.","Decentralised costs more, not less.","Control is better in central filing."]},{"u":"Unit 1","t":"Filing","n":70,"q":"Arranging files in A-to-Z order is","o":["numerical filing","geographical filing","alphabetical filing","chronological filing"],"a":2,"e":"A to Z arrangement is alphabetical filing.","g":1,"w":["Numerical uses numbers.","Geographical uses place.","","Chronological uses date."]},{"u":"Unit 1","t":"Filing","n":71,"q":"Assigning each file a number is","o":["numerical filing","geographical filing","alphabetical filing","subject filing"],"a":0,"e":"Giving each file a number is numerical filing.","g":1,"w":["","Geographical uses place.","Alphabetical uses letters.","Subject uses topic."]},{"u":"Unit 1","t":"Filing","n":72,"q":"Arranging documents by place such as state or city is","o":["chronological filing","numerical filing","subject filing","geographical filing"],"a":3,"e":"Arranging by state or city is geographical filing.","g":1,"w":["Chronological uses date.","Numerical uses number.","Subject uses topic.",""]},{"u":"Unit 1","t":"Filing","n":73,"q":"Arranging documents by date is","o":["geographical filing","alphabetical filing","chronological filing","subject filing"],"a":2,"e":"Arranging by date is chronological filing.","g":1,"w":["Geographical uses place.","Alphabetical uses letters.","","Subject uses topic."]},{"u":"Unit 1","t":"Filing","n":74,"q":"A combination of letters and numbers such as HR-101 is","o":["geographical filing","alphanumeric filing","numerical filing","chronological filing"],"a":1,"e":"Letters plus numbers (HR-101) is alphanumeric.","g":1,"w":["Geographical uses place.","","Numerical uses numbers only.","Chronological uses date."]},{"u":"Unit 1","t":"Filing","n":75,"q":"Which is the first step in the filing procedure?","o":["Retrieval","Transfer","Retention","Order to file"],"a":3,"e":"The procedure starts with the order to file.","g":1,"w":["Retrieval is later.","Transfer is later.","Retention is later.",""]},{"u":"Unit 1","t":"Filing","n":76,"q":"A reminder attached to a document that needs future action is a","o":["follow-up slip","agenda","index card","visitor pass"],"a":0,"e":"A follow-up slip reminds about future action on a document.","g":1,"w":["","An agenda lists meeting items.","An index card locates files.","A visitor pass admits visitors."]},{"u":"Unit 1","t":"Indexing","n":77,"q":"Indexing is the process of","o":["photocopying the documents so that duplicate copies are available","destroying old files that are no longer required by the office","storing the documents in cabinets in a safe and orderly manner","preparing a guide that shows where a document is filed"],"a":3,"e":"Indexing makes a guide that shows where a document is filed.","g":1,"w":["Photocopying is duplicating.","Destroying files is weeding.","Storing is filing.",""]},{"u":"Unit 1","t":"Indexing","n":78,"q":"The relationship between filing and indexing is that they are","o":["unrelated, as one deals with letters and the other with accounts","opposite activities, since indexing destroys what filing stores","one and the same activity carried out by the same clerk","complementary activities"],"a":3,"e":"Filing stores and indexing helps find - they are complementary.","g":1,"w":["They are related.","Indexing does not destroy.","They are two activities.",""]},{"u":"Unit 1","t":"Indexing","n":79,"q":"Information recorded in a bound register, e.g. a school admission register, is a","o":["visible card index","strip index","computerised index","page (bound book) index"],"a":3,"e":"A bound register is a page (bound book) index.","g":1,"w":["Visible card index uses cards in frames.","Strip index uses strips.","Computerised index uses a computer.",""]},{"u":"Unit 1","t":"Indexing","n":80,"q":"Each record on a separate card stored vertically in trays is a","o":["loose / vertical card index","strip index","wheel (rotary) index","page (bound book) index"],"a":0,"e":"Separate cards in trays form a loose (vertical) card index.","g":1,"w":["","A strip index uses strips.","A wheel index rotates.","A page index is in a book."]},{"u":"Unit 1","t":"Indexing","n":81,"q":"Cards arranged so that important information remains visible without removing them is a","o":["visible card index","strip index","page index","wheel index"],"a":0,"e":"A visible card index keeps cards in a frame so the key details stay in view without pulling the card out.","g":1,"w":["","A strip index uses strips in a holder.","A page index is in a bound book.","A wheel index rotates cards on a drum."]},{"u":"Unit 1","t":"Indexing","n":82,"q":"Information on removable strips in a holder, such as an office telephone directory, is a","o":["page index","strip index","computerised index","visible card index"],"a":1,"e":"A strip index holds removable strips in a holder - handy for a telephone directory that changes often.","g":1,"w":["A page index is a bound book.","","A computerised index uses a computer.","A visible card index keeps cards in a frame."]},{"u":"Unit 1","t":"Indexing","n":83,"q":"Cards mounted on a rotating drum for quick access form a","o":["wheel (rotary) index","visible card index","loose or vertical card index","page (bound book) index"],"a":0,"e":"Cards on a rotating drum is a wheel (rotary) index.","g":1,"w":["","A visible card index keeps cards in a frame.","A loose card index is stored in trays.","A page index is a bound book."]},{"u":"Unit 1","t":"Record Management","n":84,"q":"Which concept is broader: filing, indexing or record management?","o":["Filing","Typing","Record management","Indexing"],"a":2,"e":"Record management covers the whole life of records and includes filing and indexing.","g":1,"w":["Filing is only a part.","Typing is a communication task.","","Indexing is only a part."]},{"u":"Unit 1","t":"Record Management","n":85,"q":"Weeding of old records means","o":["indexing the records according to a numerical code","photocopying old records for use in the office","removing obsolete or unnecessary records from active files","adding new records to the active files of the office"],"a":2,"e":"Weeding removes obsolete records from active files.","g":1,"w":["Indexing is not weeding.","Photocopying is not weeding.","","Adding records is the opposite."]},{"u":"Unit 1","t":"Record Management","n":86,"q":"Digitisation is","o":["typing letters on a computer and printing them for dispatch","converting physical documents into digital form","destroying paper records after they are used once","storing paper records in fire-proof steel cabinets"],"a":1,"e":"Digitisation turns paper into digital files.","g":1,"w":["Typing and printing is not digitising.","","Destroying after one use is disposal.","Fireproof cabinets are physical storage."]},{"u":"Unit 1","t":"Office Etiquette","n":87,"q":"Office etiquette is","o":["the layout of furniture and equipment in the office building","the system of filing and indexing office documents","the code of conduct governing professional behaviour in the workplace","the set of procedures followed for purchasing office supplies"],"a":2,"e":"Etiquette is the code of conduct for professional behaviour.","g":1,"w":["Furniture arrangement is layout.","Filing is record keeping.","","Purchasing steps are procedures."]},{"u":"Unit 1","t":"Office Etiquette","n":88,"q":"Which is a DO of office etiquette?","o":["Take personal calls loudly","Reach office on time and reply promptly","Gossip about colleagues","Interrupt colleagues"],"a":1,"e":"Punctuality and prompt replies are good etiquette.","g":1,"w":["Loud personal calls disturb others.","","Gossip is a don't.","Interrupting is rude."]},{"u":"Unit 1","t":"Office Etiquette","n":89,"q":"Which is a DON'T of office etiquette?","o":["Gossiping and office politics","Being punctual","Appreciating colleagues","Respecting privacy"],"a":0,"e":"Gossip and office politics are a don't.","g":1,"w":["","Punctuality is a do.","Appreciating colleagues is a do.","Respecting privacy is a do."]},{"u":"Unit 1","t":"Office Correspondence","n":90,"q":"Communication within the organisation through memos, circulars and notices is","o":["internal correspondence","advertising","external correspondence","auditing"],"a":0,"e":"Memos, circulars and notices travel inside the firm: internal correspondence.","g":1,"w":["","Advertising is promotion.","External correspondence goes outside.","Auditing is checking accounts."]},{"u":"Unit 2","t":"Secretary","n":91,"q":"A Secretary who assists one executive personally with diary and correspondence is a","o":["private secretary","company auditor","director","office / administrative secretary"],"a":0,"e":"A private secretary serves one executive personally.","g":1,"w":["","An auditor checks accounts.","A director governs the company.","An office secretary supports a whole department."]},{"u":"Unit 2","t":"Secretary","n":92,"q":"Which is a quality of a good secretary?","o":["Poor organisational ability and bad time management","Confidentiality and integrity","Disclosing the secrets of the employer to outsiders","Carelessness and lack of discipline in the handling of work"],"a":1,"e":"A secretary handles secrets, so confidentiality and integrity matter most.","g":1,"w":["Poor organisation harms the work.","","Disclosing secrets breaks trust.","Carelessness harms the work."]},{"u":"Unit 2","t":"Secretary","n":93,"q":"Safeguarding sensitive files, salary data and executive decisions shows the secretary's","o":["dress sense and personal grooming","typing speed and shorthand skill","confidentiality and integrity","time management and punctuality"],"a":2,"e":"Guarding sensitive data shows confidentiality and integrity.","g":1,"w":["Dress sense is appearance.","Typing speed is a skill.","","Time management is about schedules."]},{"u":"Unit 2","t":"Secretary","n":94,"q":"Which is a duty of a secretary?","o":["Manufacturing goods and supervising the factory workers","Managing diary and appointments, correspondence and records","Fixing the wage rates for all the employees of the firm","Auditing the annual accounts of the company independently"],"a":1,"e":"A secretary manages the diary, correspondence and records.","g":1,"w":["Manufacturing is production.","","Fixing wages is HR's duty.","Independent auditing is the auditor's duty."]},{"u":"Unit 2","t":"Business Letter","n":95,"q":"A business letter is a","o":["private written message exchanged between two friends or relatives","spoken order given by the manager to a subordinate in the office","short note written on the file for the purpose of reference","formal written communication to conduct official business"],"a":3,"e":"A business letter is formal written communication for official business.","g":1,"w":["A friend's message is private.","An oral order is not written.","A file note is an internal note.",""]},{"u":"Unit 2","t":"Business Letter","n":96,"q":"Which is a function of a business letter?","o":["Avoids any written record of the dealings between two firms","Creates a permanent record and builds goodwill","Reduces trust and goodwill between the sender and the receiver","Replaces the need for any payment between buyer and seller"],"a":1,"e":"Business letters keep a permanent record and build goodwill.","g":1,"w":["They create, not avoid, records.","","They should build trust.","They do not replace payment."]},{"u":"Unit 2","t":"Business Letter","n":97,"q":"Which part comes right after the inside (receiver's) address in the standard format?","o":["Signature","Complimentary close","Subject line","Letterhead"],"a":2,"e":"Order: letterhead, reference/date, inside address, then subject line.","g":1,"w":["Signature comes at the end.","Complimentary close comes near the end.","","Letterhead is at the top."]},{"u":"Unit 2","t":"Business Letter","n":98,"q":"'Dear Sir/Madam' is the","o":["signature","complimentary close","salutation","subject line"],"a":2,"e":"'Dear Sir/Madam' greets the receiver: salutation.","g":1,"w":["Signature is the sender's name.","Complimentary close ends the letter.","","Subject line states the topic."]},{"u":"Unit 2","t":"Business Letter","n":99,"q":"'Yours faithfully' is the","o":["reference line","complimentary close","inside address","subject line"],"a":1,"e":"'Yours faithfully' closes the letter before the signature.","g":1,"w":["Reference line gives the file number.","","Inside address is the receiver's address.","Subject line gives the topic."]},{"u":"Unit 2","t":"Notice","n":100,"q":"A notice is a","o":["written record of the decisions taken at a meeting of directors","private letter sent to a single individual about a personal matter","formal written announcement issued to inform a specific group about an event, meeting or decision","list of the items to be discussed at a forthcoming meeting"],"a":2,"e":"A notice is a formal written announcement to a group about an event or decision.","g":1,"w":["Minutes record decisions.","A private letter is personal.","","An agenda lists items."]},{"u":"Unit 2","t":"Notice","n":101,"q":"Which element is NOT part of a notice?","o":["The date on which the notice is issued","Complimentary close such as 'Yours faithfully'","Signature and designation of the person issuing it","The word NOTICE written as the heading"],"a":1,"e":"A notice has no 'Yours faithfully' - that belongs to letters.","g":1,"w":["The date is part of it.","","The issuer's signature is part of it.","The heading NOTICE is part of it."]},{"u":"Unit 2","t":"Agenda","n":102,"q":"An agenda is","o":["a written announcement of a holiday issued to all employees","a list of items to be discussed in a meeting, circulated in advance","the official record of what was decided at a meeting","a letter inviting the shareholders to attend the annual meeting"],"a":1,"e":"An agenda lists the items to be discussed and is sent before the meeting.","g":1,"w":["A holiday announcement is a notice.","","Minutes are the decisions record.","An invitation letter is a letter."]},{"u":"Unit 2","t":"Agenda","n":103,"q":"'Any other matter with permission of the Chair' appears at the end of an","o":["agenda","memo","circular","invoice"],"a":0,"e":"'Any other business' ends an agenda so members can raise new points.","g":1,"w":["","A memo is a short note.","A circular is a mass message.","An invoice is a bill."]},{"u":"Unit 2","t":"Memo","n":104,"q":"A memorandum is used for","o":["legal notice issued to an employee for misconduct at work","brief internal communication within the same organisation","formal communication sent to customers and suppliers outside the firm","advertisement published in newspapers about job vacancies"],"a":1,"e":"A memo is brief and used inside the organisation.","g":1,"w":["A legal notice is formal.","","Customers and suppliers get letters.","Job ads are advertisements."]},{"u":"Unit 2","t":"Memo","n":105,"q":"Submission of monthly attendance reports to the Administrative Office is typically communicated through a","o":["business letter to customers","memorandum","invoice","advertisement"],"a":1,"e":"Routine reports inside the firm go by memorandum.","g":1,"w":["Customer letters are external.","","Invoices are bills.","Advertisements are for the public."]},{"u":"Unit 2","t":"Circular","n":106,"q":"A circular is","o":["a private message sent to a single person in the organisation","a reply sent to a customer who has made an enquiry","a record of the decisions of a meeting kept in the minutes book","the same message sent simultaneously to a large number of people"],"a":3,"e":"A circular sends the same message to many people at once.","g":1,"w":["Private messages are individual.","A customer reply is a letter.","Minutes record decisions.",""]},{"u":"Unit 2","t":"Circular","n":107,"q":"An announcement of revised office timings for all employees in all branches is best sent as a","o":["memo to one person","private email","circular","quotation"],"a":2,"e":"Timings for all employees in all branches need a circular.","g":1,"w":["A memo to one person is too limited.","A private email is personal.","","A quotation is a price offer."]},{"u":"Unit 2","t":"Email","n":108,"q":"Which is part of good email etiquette?","o":["A clear, specific subject line and proofreading before sending","Leaving the subject line blank and writing many topics in one mail","Using capital letters and slang in every sentence of the mail","Sending the mail without proofreading and using Reply All always"],"a":0,"e":"A clear subject line and proofreading are good email manners.","g":1,"w":["","A blank subject and mixed topics confuse.","Capitals and slang are unprofessional.","Not proofreading and overusing Reply All is poor."]},{"u":"Unit 2","t":"Email","n":109,"q":"Email has largely replaced physical letters for","o":["the printing of high quality brochures and catalogues","the transport of heavy goods and raw materials over long distances","fast, documented, day-to-day business communication","legal court notices and orders issued under the law"],"a":2,"e":"Email is quick and keeps a record for daily business.","g":1,"w":["Brochure printing is a printing job.","Heavy goods cannot be emailed.","","Court notices need formal service."]},{"u":"Unit 2","t":"Reception","n":110,"q":"The reception desk is the organisation's","o":["last point of contact","first point of contact","accounts office","storage room"],"a":1,"e":"Reception is where visitors first meet the organisation.","g":1,"w":["It is the first, not last, contact.","","It is not the accounts office.","It is not a storeroom."]},{"u":"Unit 2","t":"Reception","n":111,"q":"What should the receptionist do immediately after greeting a visitor?","o":["Verify the purpose of the visit","Ignore the visitor","Let the visitor enter any cabin","Ask for payment"],"a":0,"e":"After greeting, check why the visitor has come.","g":1,"w":["","Ignoring is rude.","Entering any cabin breaks security.","Asking for payment is not the step."]},{"u":"Unit 2","t":"Reception","n":112,"q":"A visitor register is used to","o":["record the purchase orders received from the customers","record entry details and issue a visitor pass","record the salaries and allowances paid to the employees","record the minutes of the meetings held in the organisation"],"a":1,"e":"A visitor register records entry details and the pass.","g":1,"w":["Purchase orders are recorded elsewhere.","","Salaries are payroll records.","Minutes are in the minutes book."]},{"u":"Unit 2","t":"Telephone","n":113,"q":"Which is a DO of telephone etiquette?","o":["Answer within 2-3 rings and identify yourself","Say a blunt 'Hello' and wait for the caller to speak first","Leave the caller on hold for a long time without any update","Eat or chew gum while talking to the caller"],"a":0,"e":"Answer within 2-3 rings and give your name.","g":1,"w":["","A blunt hello is unprofessional.","Long holds annoy callers.","Eating on a call is rude."]},{"u":"Unit 2","t":"Telephone","n":114,"q":"Which is a DON'T of telephone etiquette?","o":["Speak clearly at a moderate pace to the caller","Give confidential information over the phone","Take accurate messages including name, number and purpose","Confirm the details and close the call politely"],"a":1,"e":"Confidential information must never be given on the phone.","g":1,"w":["Speaking clearly is a do.","","Taking accurate messages is a do.","Confirming and closing politely is a do."]},{"u":"Unit 2","t":"Appointment","n":115,"q":"Appointment scheduling means","o":["recording the minutes of the meeting held with visitors","preparing the list of the items to be discussed at a meeting","planning and confirming meeting times between an executive and visitors to avoid clashes","cancelling all the meetings of the executive for the day"],"a":2,"e":"Scheduling plans and confirms meeting times without clashes.","g":1,"w":["Minutes record meetings.","An agenda lists items.","","Cancelling all meetings is not scheduling."]},{"u":"Unit 2","t":"Appointment","n":116,"q":"Which is a digital tool used for appointment scheduling?","o":["Carbon paper and rubber stamp","Google Calendar / Outlook Calendar","Punched card and tabulator","Typewriter and ribbon"],"a":1,"e":"Google or Outlook Calendar are digital scheduling tools.","g":1,"w":["Carbon paper and stamps are old tools.","","Punched cards are obsolete.","Typewriters are old tools."]},{"u":"Unit 2","t":"Mail Handling","n":117,"q":"The mail received by an organisation from outside is called","o":["circular","inward mail (dak)","internal memo","outward mail"],"a":1,"e":"Mail coming in from outside is inward mail.","g":1,"w":["A circular is a mass message.","","A memo is internal.","Outward mail goes out."]},{"u":"Unit 2","t":"Mail Handling","n":118,"q":"Which is the correct order of steps for inward mail?","o":["Receiving, sorting, opening and stamping, recording, distribution","Sorting, distribution, receiving, recording","Distribution, recording, receiving, sorting","Recording, receiving, distribution, sorting"],"a":0,"e":"Inward mail is received, sorted, opened and stamped, recorded, then distributed.","g":1,"w":["","Sorting cannot come after distribution.","Distribution cannot come first.","Recording cannot come before receiving."]},{"u":"Unit 2","t":"Mail Handling","n":119,"q":"Which mail is generally NOT opened by the mail clerk?","o":["Ordinary mail addressed to the organisation","Registered mail addressed to the organisation","Circulars sent by the dealers and suppliers","Mail marked 'confidential'"],"a":3,"e":"Confidential mail goes unopened to the person named.","g":1,"w":["Ordinary mail is opened.","Registered mail is opened and recorded.","Circulars are opened.",""]},{"u":"Unit 2","t":"Mail Handling","n":120,"q":"The register in which incoming mail is entered with serial number, sender and subject is the","o":["Inward Mail Register","Minutes Book","Outward Mail Register","Visitor Register"],"a":0,"e":"The Inward Mail Register logs incoming mail.","g":1,"w":["","Minutes Book records meetings.","Outward register logs dispatches.","Visitor register logs visitors."]},{"u":"Unit 2","t":"Mail Handling","n":121,"q":"Which is the correct order of steps for outward mail?","o":["Approval, dispatch, enveloping, drafting","Drafting, approval, recording, enveloping, dispatch","Recording, dispatch, drafting, approval","Dispatch, drafting, approval, recording"],"a":1,"e":"Outward mail: draft, approve, record, envelope, dispatch.","g":1,"w":["Dispatch cannot precede enveloping.","","Recording cannot precede approval.","Dispatch cannot come first."]},{"u":"Unit 2","t":"Office Communication","n":122,"q":"An internal telephone exchange linking all departments is","o":["Video conferencing","Intranet portal","Fax machine","Intercom / EPABX"],"a":3,"e":"An intercom/EPABX connects internal phones.","g":1,"w":["Video conferencing is online meetings.","Intranet is a private website.","A fax sends documents.",""]},{"u":"Unit 2","t":"Office Communication","n":123,"q":"Zoom, MS Teams and Google Meet are examples of","o":["intranet portals for circulars and HR forms","filing and indexing systems for office records","office machines used for printing and copying","video conferencing tools"],"a":3,"e":"Zoom, Teams and Meet are video conferencing tools.","g":1,"w":["Intranet portals are internal websites.","They are not filing systems.","They are software, not machines.",""]},{"u":"Unit 2","t":"Office Communication","n":124,"q":"Internal websites for circulars, HR forms and notices are called","o":["internet cafés","public blogs","intranet portals","fax machines"],"a":2,"e":"An intranet portal is the private internal website.","g":1,"w":["An internet cafe is public.","A public blog is public.","","A fax is a machine."]},{"u":"Unit 2","t":"Office Automation","n":125,"q":"Using software to perform routine office tasks automatically is","o":["office automation","manual processing","dictation","typing"],"a":0,"e":"Office automation uses software for routine tasks.","g":1,"w":["","Manual processing is by hand.","Dictation is speaking to a typist.","Typing is by hand."]},{"u":"Unit 2","t":"Office Automation","n":126,"q":"An online leave portal replacing a paper leave application is an example of","o":["a manual filing practice kept in steel cabinets","a type of lockout declared by the employer","a method of recording the minutes of meetings","a paperless office practice"],"a":3,"e":"An online leave portal replaces paper forms.","g":1,"w":["Steel cabinets store paper.","Lockout is an employer act.","Minutes recording is another task.",""]},{"u":"Unit 2","t":"Office Automation","n":127,"q":"Which is an advantage of using AI tools in offices?","o":["Removes the need for any human supervision of the output","Saves time by automating routine tasks","Increases manual errors and the time spent on routine work","Stops communication between the departments of the firm"],"a":1,"e":"AI tools save time by automating routine work.","g":1,"w":["Human supervision is still needed.","","AI reduces errors.","AI helps communication."]},{"u":"Unit 2","t":"Office Automation","n":128,"q":"Which is a smart-office task that AI tools can assist with?","o":["Manufacturing steel, packing it and loading it on trucks","Cultivating crops, harvesting them and storing the grain","Scheduling, email writing and meeting summaries","Printing currency notes and distributing them to banks"],"a":2,"e":"AI can help with scheduling, emails and meeting summaries.","g":1,"w":["Steel manufacturing is industrial.","Farming is agriculture.","","Printing currency is done by mints."],"x":1},{"u":"Unit 3","t":"Office Forms","n":129,"q":"An office form is","o":["an oral instruction given by a superior to his subordinate","a private diary maintained by the manager for personal reference","a letter written freely by an employee without any fixed format","a printed or digital document with blank spaces in a fixed format to collect specific information"],"a":3,"e":"An office form has blanks in a fixed format to collect set information.","g":1,"w":["An oral instruction is spoken.","A private diary is personal.","A free-format letter is not a form.",""]},{"u":"Unit 3","t":"Office Forms","n":130,"q":"Which is an importance of office forms?","o":["Wastes paper deliberately","Reduces coordination","Increases errors","Saves time and ensures accuracy"],"a":3,"e":"Forms save time and make data accurate.","g":1,"w":["They save paper.","They improve coordination.","They reduce errors.",""]},{"u":"Unit 3","t":"Office Forms","n":131,"q":"A leave application form is an example of","o":["a tax return","an internal form","an invoice","an external form"],"a":1,"e":"A leave form is used inside the firm: internal form.","g":1,"w":["A tax return goes to the government.","","An invoice is a bill.","External forms are used with outsiders."]},{"u":"Unit 3","t":"Office Forms","n":132,"q":"A purchase order is an example of","o":["an external form","an internal form","a memo","a record form only"],"a":0,"e":"A purchase order goes to a supplier outside: external form.","g":1,"w":["","Internal forms stay in the firm.","A memo is a note.","It is not only a record."]},{"u":"Unit 3","t":"Office Forms","n":133,"q":"A stock ledger card is an example of a","o":["record form","report form","operating form","manifold form"],"a":0,"e":"A stock ledger card records stock: record form.","g":1,"w":["","Report forms show summaries.","Operating forms are for tasks.","Manifold forms have copies."]},{"u":"Unit 3","t":"Office Forms","n":134,"q":"Forms with carbon or NCR copies for simultaneous distribution are","o":["operating forms used for routine operations of the office","report forms used to present summarised information","multiple-copy (manifold) forms","single-copy forms used only once with no duplicate"],"a":2,"e":"Carbon or NCR copies give multiple copies at once: manifold forms.","g":1,"w":["Operating forms are for routine.","Report forms give summaries.","","Single-copy forms have no duplicate."]},{"u":"Unit 3","t":"Office Forms","n":135,"q":"Which is an objective of forms?","o":["To make the recording of data different in each department","To make the checking of information difficult for managers","To increase unnecessary paperwork in the office","To standardise the procedure of recording data"],"a":3,"e":"Forms standardise how data is recorded.","g":1,"w":["They make recording uniform.","They make checking easier.","They reduce paperwork.",""]},{"u":"Unit 3","t":"Forms Design","n":136,"q":"Which is a principle of forms design?","o":["Unclear headings and absence of a title or code number","Complexity and random order of the items on the form","Very little space for writing the entries by the user","Simplicity and logical sequence"],"a":3,"e":"Good forms are simple and logically ordered.","g":1,"w":["Missing titles is a fault.","Complexity is a fault.","Too little space is a fault.",""]},{"u":"Unit 3","t":"Forms Design","n":137,"q":"Giving each form a title and serial or code number follows the principle of","o":["adequate space","identification","economy","simplicity"],"a":1,"e":"A title and code number identify the form.","g":1,"w":["Adequate space means room to write.","","Economy means no waste.","Simplicity means easy to fill."]},{"u":"Unit 3","t":"Forms Design","n":138,"q":"Avoiding unnecessary items and keeping the form short follows the principle of","o":["economy","authorisation","adequate space","identification"],"a":0,"e":"Dropping unneeded items keeps the form economical.","g":1,"w":["","Authorisation is a signature field.","Adequate space is room to write.","Identification is the code number."]},{"u":"Unit 3","t":"Forms Control","n":139,"q":"Forms control means","o":["hiding the forms from the users so that they cannot be misused","printing as many forms as possible to avoid a shortage in the office","stopping the use of all forms and relying only on oral communication","systematically designing, producing, distributing and reviewing forms to avoid duplication and waste"],"a":3,"e":"Forms control manages design, printing, distribution and review.","g":1,"w":["Hiding forms is not control.","Printing as many as possible wastes.","Stopping forms is not control.",""]},{"u":"Unit 3","t":"Forms Control","n":140,"q":"Which is a step in forms control?","o":["Avoiding any review of the forms once they are introduced","Printing duplicate forms and ignoring the obsolete ones","Numbering and indexing, periodic review and standardisation","Allowing any department to design forms without approval"],"a":2,"e":"Numbering, indexing, review and standardisation control forms.","g":1,"w":["No review leaves outdated forms.","Ignoring obsolete forms causes errors.","","Unapproved designs cause chaos."]},{"u":"Unit 3","t":"Forms Control","n":141,"q":"Version control on a form helps to","o":["increase the printing cost of the forms in the office","identify the latest approved version and avoid use of old forms","hide the forms from the users who are not authorised","duplicate the forms so that every employee has many copies"],"a":1,"e":"Version control shows the latest approved form.","g":1,"w":["It does not aim to raise cost.","","It does not hide forms.","It does not duplicate forms."]},{"u":"Unit 3","t":"Forms Preparation","n":142,"q":"What is the FIRST step in preparing a form?","o":["Choose the size of paper and the number of copies","Print the form and distribute it to all the users","Get the draft of the form approved by the authority","Identify the purpose the form must serve"],"a":3,"e":"First, decide what purpose the form serves.","g":1,"w":["Size and copies come after purpose.","Printing comes last.","Approval comes after drafting.",""]},{"u":"Unit 3","t":"Forms Preparation","n":143,"q":"A leave application form generally includes","o":["purchase order numbers, delivery dates and quantities ordered","stock details, supplier invoices and the price list of products","tax rates, depreciation charges and the profit of the company","employee details, leave details and authorisation fields"],"a":3,"e":"A leave form has employee, leave and approval details.","g":1,"w":["Purchase details belong to order forms.","Stock details belong to inventory forms.","Tax and profit belong to financial forms.",""]},{"u":"Unit 3","t":"Record Management","n":144,"q":"Record management is","o":["only the destruction of the documents after a year of use","only the typing and the photocopying of the documents","only the buying of folders and files for the use of the office","the systematic control of creation, maintenance, use, storage, retrieval and disposal of business records"],"a":3,"e":"Record management controls records from creation to disposal.","g":1,"w":["It is more than destruction.","It is more than typing.","It is more than buying files.",""]},{"u":"Unit 3","t":"Record Management","n":145,"q":"A record is","o":["a rubber stamp used for marking the received date on mail","a blank form that has not yet been filled by anyone","any document, paper or electronic, created or received as evidence of a business activity","a tool used for punching holes in the sheets of paper"],"a":2,"e":"A record is any document kept as evidence of business activity.","g":1,"w":["A date stamp is a tool.","A blank form is not yet a record.","","A punch is a tool."]},{"u":"Unit 3","t":"Record Management","n":146,"q":"Which is the correct life cycle of a record?","o":["Retention, creation, disposal, active use, storage","Storage, disposal, creation, retention, active use","Disposal, creation, storage, active use, retention","Creation, active use, storage, retention, disposal / archiving"],"a":3,"e":"Life cycle: creation, active use, storage, retention, disposal.","g":1,"w":["Retention cannot be first.","Storage cannot come before creation.","Disposal cannot be first.",""]},{"u":"Unit 3","t":"Record Management","n":147,"q":"Which statement is correct about forms and records?","o":["Forms and records are identical","A form asks for information; a record preserves information","Records are always blank","A record asks for information; a form preserves it"],"a":1,"e":"A form collects information; a record keeps it as evidence.","g":1,"w":["They are different.","","Records are filled, not blank.","That reverses the roles."]},{"u":"Unit 3","t":"Record Keeping","n":148,"q":"Which is a need / importance of record keeping?","o":["Increasing the duplication of work in the departments","Legal evidence and statutory compliance","Avoiding the evidence of the business transactions","Hiding the information from the auditors of the firm"],"a":1,"e":"Records serve as legal proof and compliance.","g":1,"w":["They reduce duplication.","","They provide evidence.","They are not meant to hide information."]},{"u":"Unit 3","t":"Record Keeping","n":149,"q":"Records serving as proof in audits and disputes shows the importance of","o":["storage space","typing","quick retrieval","legal evidence"],"a":3,"e":"Proof in audits and disputes is legal evidence.","g":1,"w":["Storage space is capacity.","Typing is a skill.","Quick retrieval is speed.",""]},{"u":"Unit 3","t":"Record Keeping","n":150,"q":"A signed contract kept in a physical archive with a scanned PDF in a document management system is","o":["no record keeping","hybrid record keeping","manual record keeping only","electronic record keeping only"],"a":1,"e":"Physical plus digital copies is hybrid record keeping.","g":1,"w":["A kept contract is record keeping.","","Manual only has no PDF.","Electronic only has no archive."]},{"u":"Unit 3","t":"Record Keeping","n":151,"q":"Classification of records on the basis of importance includes","o":["red, blue and green records according to the colour of the files","front, middle and back records according to the location in the office","vital, important, useful and non-essential records","internal and external records according to the department concerned"],"a":2,"e":"Importance classes: vital, important, useful, non-essential.","g":1,"w":["Colour is not importance.","Location is not importance.","","Internal/external is origin."]},{"u":"Unit 3","t":"Record Keeping","n":152,"q":"Irreplaceable records such as title deeds and legal agreements are","o":["useful records","non-essential records","inactive records only","vital records"],"a":3,"e":"Irreplaceable records are vital records.","g":1,"w":["Useful records can be replaced.","Non-essential records have no value.","Inactive refers to use, not value.",""]},{"u":"Unit 3","t":"Record Keeping","n":153,"q":"Records frequently referred to in current operations are","o":["active records","vital records only","non-essential records","inactive records"],"a":0,"e":"Records used often are active records.","g":1,"w":["","Vital refers to importance.","Non-essential refers to value.","Inactive are rarely used."]},{"u":"Unit 3","t":"Record Preservation","n":154,"q":"Which is a method of preserving records?","o":["Retention schedule, proper storage and digital backup","Leaving the records in the open and sharing the passwords freely","Avoiding any indexing and storing records in a random order","Keeping a single copy in a damp room without any backup"],"a":0,"e":"Retention schedules, proper storage and backup preserve records.","g":1,"w":["","Open storage and shared passwords are unsafe.","No indexing causes loss.","A damp room destroys records."]},{"u":"Unit 3","t":"Record Preservation","n":155,"q":"A retention schedule fixes","o":["how long each type of record must be kept before disposal","the colour and size of the files used for different departments","the salary and allowances payable to the records clerk","the working hours and the leave entitlement of the office staff"],"a":0,"e":"A retention schedule says how long to keep each record.","g":1,"w":["","Colour/size of files is separate.","Clerk's pay is HR.","Working hours are HR rules."]},{"u":"Unit 3","t":"Centralisation","n":156,"q":"Which is an advantage of centralised record keeping?","o":["Uniformity in filing and avoiding duplication","Department-specific control","Faster access for every department always","No risk of overload"],"a":0,"e":"Centralised keeping gives uniform filing and avoids duplication.","g":1,"w":["","Departmental control is decentralised.","Access can be slower.","The central unit can be overloaded."]},{"u":"Unit 3","t":"Centralisation","n":157,"q":"Which is an advantage of decentralised record keeping?","o":["Lower overall cost of the staff and space for records","Perfect uniformity in the filing methods used by all the departments","No duplication of records across departments of the firm","Quick access for the department's own needs"],"a":3,"e":"Decentralised keeping gives each department quick access.","g":1,"w":["Cost is usually higher.","Uniformity is a centralised strength.","Duplication is a decentralised weakness.",""]},{"u":"Unit 3","t":"Digital Records","n":158,"q":"OCR in digital record systems is used to","o":["photocopy the documents for circulation to the departments","print the forms on pre-numbered paper in large numbers","convert paper records into searchable digital text","destroy the paper records securely after they have been used"],"a":2,"e":"OCR converts scanned paper into searchable text.","g":1,"w":["Photocopying is copying.","Printing forms is another task.","","Shredding destroys."]},{"u":"Unit 3","t":"Digital Records","n":159,"q":"Which is a digital record system?","o":["Rubber stamp and ink pad","Document Management System (DMS)","Steel filing cabinet with a lock","Carbon paper and a typewriter"],"a":1,"e":"A Document Management System is a digital record system.","g":1,"w":["A rubber stamp is a tool.","","A steel cabinet is physical.","Carbon paper and typewriter are old tools."]},{"u":"Unit 3","t":"Digital Records","n":160,"q":"Which is a challenge of digital record systems?","o":["Impossibility of sharing the records between locations","Slower retrieval of records than from the paper files","Need for large physical space for storing the records","Cybersecurity and data-privacy risks"],"a":3,"e":"Digital records face hacking and privacy risks.","g":1,"w":["They can be shared easily.","They are faster.","They save space.",""]},{"u":"Unit 4","t":"Company Secretary","n":161,"q":"A Company Secretary is classified under the Companies Act 2013 as","o":["a shareholder holding the majority of shares","a statutory auditor of the company","an independent director of the company","Key Managerial Personnel (KMP)"],"a":3,"e":"Under the Companies Act 2013 the Company Secretary is a Key Managerial Personnel (KMP).","g":1,"w":["A majority shareholder is an owner, not an officer.","The statutory auditor audits accounts independently.","An independent director is a non-executive board member.",""]},{"u":"Unit 4","t":"Company Secretary","n":162,"q":"ICSI stands for","o":["International Company Secretaries Institute","Institute of Commerce and Secretarial Information","Institute of Company Secretaries of India","Indian Council of Secretarial Industries"],"a":2,"e":"ICSI = Institute of Company Secretaries of India, the professional body.","g":1,"w":["It is Indian, not international.","That is not the body's name.","","That name does not exist."]},{"u":"Unit 4","t":"Company Secretary","n":163,"q":"A whole-time Company Secretary is compulsory for listed companies and public companies with paid-up capital of","o":["Rs 10 crore or more","Rs 1 crore or more and with fifty or more directors","Rs 50 lakh or more and with a hundred or more employees","Rs 1 lakh or more and with five or more shareholders"],"a":0,"e":"A whole-time CS is required for listed companies and public companies with paid-up capital of Rs 10 crore or more.","g":1,"w":["","Rs 1 crore is too low.","Rs 50 lakh is too low.","Rs 1 lakh is far too low."]},{"u":"Unit 4","t":"Company Secretary","n":164,"q":"A Company Secretary is appointed by","o":["the Registrar of Companies on behalf of the central government","the customers of the company at a special meeting called for the purpose","the trade union representing the employees of the company","a resolution of the Board of Directors"],"a":3,"e":"The Board of Directors appoints the CS by resolution.","g":1,"w":["The Registrar registers, not appoints.","Customers have no say.","Unions do not appoint officers.",""]},{"u":"Unit 4","t":"Company Secretary","n":165,"q":"Which is a function of a Company Secretary?","o":["Advertising the products and handling the sales promotion campaigns","Auditing the accounts and certifying that they show a true and fair view","Manufacturing the products and supervising the production line","Maintaining minutes books and statutory registers and ensuring legal compliance"],"a":3,"e":"A CS keeps minutes books and registers and ensures legal compliance.","g":1,"w":["Advertising is marketing.","Auditing is the auditor's role.","Manufacturing is production.",""]},{"u":"Unit 4","t":"Company Secretary","n":166,"q":"Statutory duties of a secretary include","o":["recruiting factory workers and supervising their daily work","fixing the prices of the products and planning the advertisements","maintaining registers and filing returns with the ROC","selling the products and collecting the payment from customers"],"a":2,"e":"Statutory duties include maintaining registers and filing returns with the ROC.","g":1,"w":["Recruiting factory workers is HR/production.","Pricing and ads are marketing.","","Selling is the sales department's job."]},{"u":"Unit 4","t":"Company Secretary","n":167,"q":"The secretary is called a link between","o":["the trade union, the workers and the foremen of the factory","the Board, management, shareholders and authorities","the customers, suppliers, banks and the competitors of the company","the production, sales and purchase departments of the company only"],"a":1,"e":"The CS links the Board, management, shareholders and authorities.","g":1,"w":["Union and workers are labour relations.","","That describes market parties.","Only internal departments would be too narrow."]},{"u":"Unit 4","t":"Company Secretary","n":168,"q":"The secretary reports to the","o":["auditor only","Board","competitors","customers"],"a":1,"e":"The secretary reports to the Board.","g":1,"w":["He reports to more than the auditor.","","Competitors have no link.","Customers are not his boss."]},{"u":"Unit 4","t":"Directors","n":169,"q":"A director is","o":["a person appointed to the Board to participate in management, decision-making and supervision","a person employed at the lowest level to carry out routine office work","a customer who regularly purchases the company's products","an outsider appointed to audit the accounts of the company"],"a":0,"e":"A director sits on the Board and takes part in management and supervision.","g":1,"w":["","A lowest-level worker is not a director.","A customer is not a director.","An outsider auditing is an auditor."]},{"u":"Unit 4","t":"Directors","n":170,"q":"The minimum number of directors in a public company is","o":["1","15","2","3"],"a":3,"e":"A public company needs at least 3 directors.","g":1,"w":["1 is for a One Person Company.","15 is the maximum.","2 is the minimum for a private company.",""]},{"u":"Unit 4","t":"Directors","n":171,"q":"The minimum number of directors in a private company is","o":["3","7","2","1"],"a":2,"e":"A private company needs at least 2 directors.","g":1,"w":["3 is for a public company.","7 is not the minimum.","","1 is for a One Person Company."]},{"u":"Unit 4","t":"Directors","n":172,"q":"The maximum number of directors for a company (as in the notes) is","o":["50","7","15","21"],"a":2,"e":"A company can have at most 15 directors (more with a special resolution).","g":1,"w":["50 is not the figure.","7 is not the maximum.","","21 is not the notes' figure."]},{"u":"Unit 4","t":"Directors","n":173,"q":"Which is a responsibility of directors?","o":["Act in good faith, with due care and skill and avoid conflict of interest","Use their position to make secret personal gains for themselves","Act only in the interest of the majority shareholders and not the company","Avoid attending Board meetings and disclosing their interest in contracts"],"a":0,"e":"Directors must act in good faith with care and skill and avoid conflict of interest.","g":1,"w":["","Secret gains are forbidden.","They must serve the company, not only majority holders.","They must attend and disclose interest."]},{"u":"Unit 4","t":"Chairman","n":174,"q":"The Chairman is the person who","o":["manages the day-to-day business of the company as an employee","examines and verifies the accounts and reports to the shareholders","keeps the minutes book and maintains the statutory registers","presides over meetings of the Board and guides its functioning"],"a":3,"e":"The Chairman presides over Board meetings.","g":1,"w":["Day-to-day management is by the managing director.","Checking accounts is the auditor's job.","Keeping minutes is the secretary's job.",""]},{"u":"Unit 4","t":"Chairman","n":175,"q":"If votes are tied, the Chairman may use his","o":["veto power","casting vote","second quorum","proxy"],"a":1,"e":"The Chairman's casting vote breaks a tie, if the Articles allow.","g":1,"w":["A veto blocks a decision.","","Second quorum is not a term.","A proxy is a representative."]},{"u":"Unit 4","t":"Auditor","n":176,"q":"An auditor is","o":["an officer who presides over the meetings of the Board","an independent professional (Chartered Accountant) who examines the financial records and reports whether they show a true and fair view","an employee who records the day-to-day transactions in the books","a director elected by the shareholders to manage the business"],"a":1,"e":"An auditor is an independent Chartered Accountant who reports on true and fair view.","g":1,"w":["The Chairman presides over meetings.","","Employees record transactions.","Directors manage the business."]},{"u":"Unit 4","t":"Auditor","n":177,"q":"An auditor is appointed by","o":["the company secretary","employees","shareholders at the AGM","the Chairman only"],"a":2,"e":"Shareholders appoint the auditor at the AGM.","g":1,"w":["The company secretary cannot.","Employees cannot.","","The Chairman alone cannot."]},{"u":"Unit 4","t":"Meetings","n":178,"q":"A meeting is","o":["a task done by one person alone for a personal purpose","a written record of the decisions taken by the directors","a gathering of two or more persons for a common purpose","a printed notice sent to the members of a company"],"a":2,"e":"A meeting is two or more persons gathering for a common purpose.","g":1,"w":["One person alone is not a meeting.","Minutes record a meeting.","","A notice only calls a meeting."]},{"u":"Unit 4","t":"Meetings","n":179,"q":"A Board meeting must be held at least","o":["twice in a year, with a gap not above 6 months between two meetings","once in two years, with a gap not above 24 months","4 times a year, with a gap not above 120 days","once in a year, with a gap not above 12 months between two meetings"],"a":2,"e":"A Board must meet at least four times a year with no more than 120 days between meetings.","g":1,"w":["Twice a year is too few.","Once in two years is far too few.","","Once a year is too few."]},{"u":"Unit 4","t":"Meetings","n":180,"q":"The Annual General Meeting (AGM) is held","o":["every five years, within one year of the financial year end","twice a year, within three months of each half-year end","yearly, within 6 months of the financial year end","only when the directors feel that it is necessary to hold it"],"a":2,"e":"The AGM is yearly, within 6 months of year end.","g":1,"w":["Every five years is wrong.","Twice a year is wrong.","","It is mandatory, not optional."]},{"u":"Unit 4","t":"Meetings","n":181,"q":"An Extraordinary General Meeting (EGM) is","o":["held yearly","held only by the auditor","called for urgent business","a class meeting"],"a":2,"e":"An EGM is called for urgent business between AGMs.","g":1,"w":["AGMs are yearly.","The auditor does not hold it.","","A class meeting is a different meeting."]},{"u":"Unit 4","t":"Meetings","n":182,"q":"A Class Meeting is attended by","o":["the auditors and the company secretary of the company","all the members of the company holding any class of shares","all the directors of the company on the Board","one class of shareholders"],"a":3,"e":"A class meeting is attended by one class of shareholders.","g":1,"w":["Auditors and secretary are officers.","All shareholders attend a general meeting.","Directors attend Board meetings.",""]},{"u":"Unit 4","t":"Meetings","n":183,"q":"A committee meeting, e.g. audit, nomination or CSR, is attended by","o":["the customers and suppliers who have dealings with the company","selected directors / committee members","all the shareholders of the company who hold voting shares","the general public who are interested in the company's affairs"],"a":1,"e":"Committee meetings involve selected directors.","g":1,"w":["Customers and suppliers are outsiders.","","All shareholders attend general meetings.","The public is not involved."]},{"u":"Unit 4","t":"Meetings","n":184,"q":"Before a meeting, the secretary","o":["circulates the decisions and follows up the action points","files the annual returns with the Registrar of Companies","fixes date and venue, sends notice and agenda and prepares papers and attendance sheet","signs the minutes and enters them in the minutes book"],"a":2,"e":"Before the meeting the secretary fixes date and venue and sends notice, agenda and papers.","g":1,"w":["Circulating decisions is after.","Filing annual returns is separate.","","Signing minutes is after."]},{"u":"Unit 4","t":"Notice","n":185,"q":"Notice for a board meeting must be given at least","o":["30 days before","21 clear days before","7 days before","1 day before"],"a":2,"e":"Board meeting notice must be given at least 7 days before.","g":1,"w":["30 days is too long.","21 clear days is for general meetings.","","1 day is too short."]},{"u":"Unit 4","t":"Notice","n":186,"q":"Notice for a general meeting such as an AGM must be given at least","o":["5 days before","1 day before","21 clear days before","7 days before"],"a":2,"e":"A general meeting needs 21 clear days' notice.","g":1,"w":["5 days is too short.","1 day is too short.","","7 days is for Board meetings."]},{"u":"Unit 4","t":"Notice","n":187,"q":"A defective notice can","o":["avoid all disputes","improve attendance","make the meeting invalid","have no effect"],"a":2,"e":"A defective notice can make the meeting invalid.","g":1,"w":["It causes, not avoids, disputes.","It does not improve attendance.","","It does matter legally."]},{"u":"Unit 4","t":"Agenda","n":188,"q":"Which item usually appears at the end of an agenda?","o":["Call to order by the chairman of the meeting","Notice calling the meeting issued by the secretary","Any other business with Chairman's permission","Confirmation of the minutes of the previous meeting"],"a":2,"e":"'Any other business' comes last.","g":1,"w":["Call to order is first.","Notice is issued before the meeting.","","Confirming minutes is early."]},{"u":"Unit 4","t":"Quorum","n":189,"q":"Quorum means","o":["the maximum number of persons allowed to attend a meeting","the minimum attendance required to legally conduct a meeting","the number of votes cast against a proposal at the meeting","the total number of directors appointed in the company"],"a":1,"e":"Quorum is the minimum attendance needed to validly conduct a meeting.","g":1,"w":["That is not a maximum.","","Votes against is a different count.","Total directors is a different count."]},{"u":"Unit 4","t":"Quorum","n":190,"q":"The quorum for a Board meeting is","o":["all the directors of the company without any exception","one-fourth of the total directors or 1 director whichever is lower","one-half of the total directors or 5 directors whichever is higher","1/3 of total directors or 2 directors, whichever is higher"],"a":3,"e":"Board quorum is one-third of directors or 2, whichever is higher.","g":1,"w":["All directors is not required.","One-fourth or 1 is wrong.","One-half or 5 is wrong.",""]},{"u":"Unit 4","t":"Quorum","n":191,"q":"The quorum for a general meeting of a private company is","o":["30 members personally present at the meeting","15 members personally present at the meeting","5 members personally present at the meeting","2 members personally present"],"a":3,"e":"A private company's general meeting needs 2 members present.","g":1,"w":["30 is for a public company with over 5000.","15 is for a public company with 1000-5000 members.","5 is for a public company.",""]},{"u":"Unit 4","t":"Quorum","n":192,"q":"The quorum for a general meeting of a public company with up to 1000 members is","o":["15 members","2 members","5 members","30 members"],"a":2,"e":"A public company with up to 1000 members needs 5 present.","g":1,"w":["15 is for 1000-5000 members.","2 is for private companies.","","30 is for over 5000 members."]},{"u":"Unit 4","t":"Voting","n":193,"q":"Votes counted according to the voting rights of members is a","o":["show of hands","poll","proxy","postal ballot"],"a":1,"e":"A poll counts votes according to voting rights.","g":1,"w":["Show of hands counts heads.","","Proxy is a representative.","Postal ballot is a mode of voting."]},{"u":"Unit 4","t":"Voting","n":194,"q":"A member voting without being physically present, through a representative, is voting by","o":["casting vote","show of hands","proxy","poll"],"a":2,"e":"A proxy votes on behalf of an absent member.","g":1,"w":["Casting vote is the Chairman's.","Show of hands needs presence.","","A poll is a method of counting."]},{"u":"Unit 4","t":"Motion & Resolution","n":195,"q":"A formal proposal made by a member during a meeting is a","o":["quorum","motion","resolution","minute"],"a":1,"e":"A formal proposal at a meeting is a motion.","g":1,"w":["Quorum is attendance.","","A resolution is the passed decision.","A minute is a record."]},{"u":"Unit 4","t":"Motion & Resolution","n":196,"q":"A formal decision of the meeting after a motion is approved by required voting is a","o":["agenda","resolution","notice","motion"],"a":1,"e":"A motion approved by the required vote becomes a resolution.","g":1,"w":["An agenda lists items.","","A notice calls the meeting.","A motion is the proposal."]},{"u":"Unit 4","t":"Motion & Resolution","n":197,"q":"An ordinary resolution is passed by","o":["unanimity only","the Chairman alone","75% of votes","a simple majority"],"a":3,"e":"An ordinary resolution needs a simple majority.","g":1,"w":["Unanimity is not required.","The Chairman cannot pass it alone.","75% is a special resolution.",""]},{"u":"Unit 4","t":"Motion & Resolution","n":198,"q":"A special resolution requires at least","o":["75% (3/4) of votes in favour","50% of the votes cast at the meeting","a simple majority of the votes cast at the meeting","unanimous support of all the members present"],"a":0,"e":"A special resolution needs at least 75% votes in favour.","g":1,"w":["","50% is not enough.","Simple majority is ordinary.","Unanimity is not needed."]},{"u":"Unit 4","t":"Motion & Resolution","n":199,"q":"A resolution passed by papers sent to directors is a","o":["ordinary resolution","circulation resolution","poll resolution","special resolution"],"a":1,"e":"Directors passing a resolution by circulated papers is circulation resolution.","g":1,"w":["Ordinary resolution is by members.","","Poll resolution is a vote method.","Special resolution needs 75%."]},{"u":"Unit 4","t":"Minutes","n":200,"q":"Minutes are","o":["the official written record of what happened and was decided at a meeting","the sheet signed by the members present at the meeting","the written notice sent to members calling a meeting","the list of items to be discussed at the forthcoming meeting"],"a":0,"e":"Minutes are the official written record of what was decided.","g":1,"w":["","An attendance sheet lists members present.","A notice calls the meeting.","An agenda lists items."]},{"u":"Unit 4","t":"Minutes","n":201,"q":"Minutes that record only decisions and resolutions passed are","o":["minutes of attendance, which list the members present","minutes of narration, which give a summary of the discussion","minutes of resolution","minutes of agenda, which list the items to be discussed"],"a":2,"e":"Minutes of resolution record only decisions.","g":1,"w":["Attendance lists members.","Narration adds a discussion summary.","","Agenda lists items."]},{"u":"Unit 4","t":"Minutes","n":202,"q":"The minutes should be entered in the minutes book within","o":["30 days","5 years","1 year","7 days only"],"a":0,"e":"Signed minutes are entered in the minutes book within 30 days.","g":1,"w":["","5 years is too late.","1 year is too late.","7 days is not the rule."]},{"u":"Unit 4","t":"Minutes","n":203,"q":"Which rule applies to the minutes book?","o":["Erasing is allowed freely and pages may be left blank","No blank gaps and no erasing; corrections by signed note","It may be destroyed after one year from the meeting","Corrections may be made without any signature of the chairman"],"a":1,"e":"Minutes book must have no blanks or erasures; corrections by signed note.","g":1,"w":["Erasing is not allowed.","","It is kept permanently.","Corrections need the Chairman's signature."]},{"u":"Unit 4","t":"Minutes","n":204,"q":"Minutes are signed by the","o":["customer","any visitor","auditor","Chairman"],"a":3,"e":"The Chairman signs the minutes.","g":1,"w":["A customer does not.","A visitor does not.","The auditor does not.",""]},{"u":"Unit 4","t":"Meeting Documentation","n":205,"q":"Which is the correct meeting documentation flow?","o":["Follow-up, notice, minutes, agenda","Agenda, minutes, notice, follow-up","Notice, agenda, attendance, minutes, follow-up","Minutes, notice, agenda, attendance"],"a":2,"e":"Documentation flows: notice, agenda, attendance, minutes, follow-up.","g":1,"w":["Follow-up is last.","Agenda before minutes but notice comes first.","","Minutes cannot come first."]},{"u":"Unit 4","t":"Company Secretary","n":206,"q":"The Company Secretary is a Key Managerial Personnel (KMP) under","o":["Section 143 of the Companies Act, 2013","Section 203 of the Companies Act, 2013","Section 100 of the Companies Act, 2013","Section 2 of the Sale of Goods Act, 1930"],"a":1,"e":"Section 203 of the Companies Act 2013 lists KMP including the CS.","g":1,"w":["Section 143 deals with audit.","","Section 100 deals with EGMs.","The Sale of Goods Act is a different law."],"x":1},{"u":"Unit 4","t":"Company Secretary","n":207,"q":"Which professional body conducts the Company Secretary course in India?","o":["ICSI","SEBI","ICAI","ICMAI"],"a":0,"e":"ICSI conducts the CS course.","g":1,"w":["","SEBI regulates securities.","ICAI is for Chartered Accountants.","ICMAI is for cost accountants."],"x":1},{"u":"Unit 4","t":"Company Secretary","n":208,"q":"Filing annual returns and statutory forms with the Registrar of Companies (ROC) is a","o":["statutory duty of the secretary","marketing duty of the secretary relating to promotion of the products","production duty of the secretary in the factory","sales duty of the secretary to the customers of the company"],"a":0,"e":"Filing returns with the ROC is a statutory duty.","g":1,"w":["","Promotion is marketing.","Production is not a secretary's duty.","Sales is not a secretary's duty."],"x":1},{"u":"Unit 4","t":"Company Secretary","n":209,"q":"Secretarial Standards SS-1 and SS-2 issued by ICSI relate to","o":["the issue of shares and debentures by the company","income tax and the filing of returns by the company","accounting and auditing of the financial statements","Board meetings and general meetings"],"a":3,"e":"SS-1 covers Board meetings and SS-2 general meetings.","g":1,"w":["Share issue has other rules.","Tax has other rules.","Accounting and audit have other standards.",""],"x":1},{"u":"Unit 4","t":"Directors","n":210,"q":"A Director Identification Number (DIN) is","o":["type of share issued to the directors of the company","bank account number given to the directors for salary","tax number allotted to every company by the income tax department","a unique number allotted to every director"],"a":3,"e":"DIN is a unique ID allotted to every director.","g":1,"w":["A DIN is not a share type.","A bank account is separate.","A tax number for companies is TAN/PAN.",""],"x":1},{"u":"Unit 4","t":"Directors","n":211,"q":"An independent director is one who","o":["is an employee of the company holding a senior post","is the founder and the largest shareholder of the company","has no material pecuniary relationship with the company and can judge independently","is a close relative of the managing director of the company"],"a":2,"e":"An independent director has no material financial tie and judges independently.","g":1,"w":["An employee is not independent.","A founder-shareholder is not independent.","","A relative of the MD is not independent."],"x":1},{"u":"Unit 4","t":"Directors","n":212,"q":"A Managing Director is a director who","o":["is entrusted with substantial powers of management of the company's affairs","an officer who keeps the minutes and the statutory registers","only a shareholder with no role in the management of the company","an outside professional who audits the books of the company"],"a":0,"e":"A Managing Director holds substantial management powers under the Board.","g":1,"w":["","A secretary keeps minutes.","A shareholder has no management role.","An outside auditor audits."],"x":1},{"u":"Unit 4","t":"Directors","n":213,"q":"Directors act collectively as the","o":["Registrar","Board of Directors","General Body of Auditors","Trade union"],"a":1,"e":"Directors together form the Board of Directors.","g":1,"w":["The Registrar is a government officer.","","There is no General Body of Auditors.","A trade union represents workers."],"x":1},{"u":"Unit 4","t":"Auditor","n":214,"q":"An auditor of a company cannot","o":["be a director or an employee of the same company","inspect the books of accounts of the company","be a Chartered Accountant holding a valid certificate of practice","report to the shareholders on the financial statements"],"a":0,"e":"An auditor must be independent, so he cannot be a director or employee.","g":1,"w":["","Inspecting books is his job.","Being a CA is required.","Reporting to shareholders is his job."],"x":1},{"u":"Unit 4","t":"Auditor","n":215,"q":"The audit report states whether the financial statements give a","o":["full secrecy","complete profit guarantee","tax exemption","true and fair view"],"a":3,"e":"The audit report states whether accounts give a true and fair view.","g":1,"w":["Audit is about disclosure, not secrecy.","No auditor guarantees profit.","Tax exemption is not an audit outcome.",""]},{"u":"Unit 4","t":"General Meetings","n":216,"q":"The maximum gap between two Annual General Meetings should not exceed","o":["6 months","15 months","5 years","3 years"],"a":1,"e":"The gap between two AGMs must not exceed 15 months.","g":1,"w":["6 months is the time after year end.","","5 years is too long.","3 years is too long."],"x":1},{"u":"Unit 4","t":"General Meetings","n":217,"q":"Ordinary business at an AGM includes","o":["issue of new shares at a premium and the change of the registered office","alteration of the Memorandum and the sale of the whole undertaking","consideration of financial statements, declaration of dividend, appointment of directors and auditors","winding up of the company and the appointment of a liquidator"],"a":2,"e":"Ordinary business: accounts, dividend, directors and auditors.","g":1,"w":["Share issue and registered office change are special.","Altering the Memorandum is special.","","Winding up is special."],"x":1},{"u":"Unit 4","t":"General Meetings","n":218,"q":"All business other than ordinary business at an AGM, and all business at an EGM, is called","o":["casual business","annual business","routine business","special business"],"a":3,"e":"All business other than ordinary at an AGM, and all at an EGM, is special business.","g":1,"w":["Casual business is not a legal term.","Annual business is not a legal term.","Routine business is not a legal term.",""],"x":1},{"u":"Unit 4","t":"General Meetings","n":219,"q":"An EGM can be requisitioned by members holding at least","o":["1% of the voting power or paid-up capital of the company","50% of the voting power or paid-up capital of the company","10% of the voting power / paid-up capital","75% of the voting power or paid-up capital of the company"],"a":2,"e":"Members holding 10% of voting power can requisition an EGM.","g":1,"w":["1% is too small.","50% is more than required.","","75% is more than required."],"x":1},{"u":"Unit 4","t":"General Meetings","n":220,"q":"A general meeting can be called at shorter notice if consent is given by","o":["at least 95% of the members entitled to vote","the chairman of the board alone, in the interest of the company","at least 50% of the members entitled to vote at the meeting","any one director of the company in case of an emergency"],"a":0,"e":"Shorter notice needs consent of at least 95% of members entitled to vote.","g":1,"w":["","The Chairman alone cannot.","50% is not enough.","One director cannot."],"x":1},{"u":"Unit 4","t":"General Meetings","n":221,"q":"If quorum is not present within half an hour of the scheduled time, a general meeting is generally","o":["cancelled forever and the business is dropped from the agenda","held after one year when the quorum can be formed","adjourned to the same day in the next week","held without the quorum, since the business is urgent"],"a":2,"e":"Without quorum the meeting is adjourned to the same day next week.","g":1,"w":["It is not cancelled forever.","A year's wait is not required.","","Business cannot proceed without quorum."],"x":1},{"u":"Unit 4","t":"General Meetings","n":222,"q":"To adjourn a meeting without fixing a date for the next meeting is to adjourn","o":["ex parte","suo motu","sine die","pro rata"],"a":2,"e":"Adjourning with no date fixed is 'sine die'.","g":1,"w":["Ex parte means one side only.","Suo motu means on its own motion.","","Pro rata means proportionate."],"x":1},{"u":"Unit 4","t":"Voting","n":223,"q":"A proxy is a person who","o":["presides over the meeting and signs the minutes","keeps the notes of the meeting and drafts the minutes","attends and votes on behalf of a member who cannot attend","audits the proceedings of the meeting and certifies them"],"a":2,"e":"A proxy attends and votes on behalf of an absent member.","g":1,"w":["The Chairman presides.","The secretary writes minutes.","","The auditor audits."],"x":1},{"u":"Unit 4","t":"Voting","n":224,"q":"A proxy generally cannot","o":["be appointed by a member who is unable to attend the meeting","hold a proxy form deposited with the company before the meeting","vote on a poll on behalf of the member who appointed him","speak at the meeting or vote on a show of hands"],"a":3,"e":"A proxy cannot speak or vote on a show of hands - only on a poll.","g":1,"w":["A proxy is appointed by an absent member.","The proxy form is deposited beforehand.","A proxy can vote on a poll.",""],"x":1},{"u":"Unit 4","t":"Voting","n":225,"q":"Voting on a show of hands is on the principle of","o":["one rupee, one vote","one share, one vote","two votes for directors","one person, one vote"],"a":3,"e":"A show of hands counts one vote per person.","g":1,"w":["One rupee one vote is not a rule.","One share one vote is a poll.","Directors do not get double votes.",""],"x":1},{"u":"Unit 4","t":"Voting","n":226,"q":"The casting vote is exercised by the Chairman","o":["only at the AGM when the dividend is to be declared","only when the votes are equally divided","never, because the chairman has no right to vote in any case","always, in addition to his ordinary vote, on every resolution"],"a":1,"e":"The casting vote is used only when votes are equal.","g":1,"w":["It is not limited to the AGM.","","A chairman can vote.","He does not vote twice always."],"x":1},{"u":"Unit 4","t":"Motion & Resolution","n":227,"q":"A special resolution requires votes in favour to be at least","o":["equal to the number of votes cast against the resolution","unanimous support from all the members of the company","more than one-half of the votes cast at the meeting","three times the votes against (75% of votes cast)"],"a":3,"e":"Special resolution: votes in favour at least three times those against (75%).","g":1,"w":["Equal votes would not pass it.","Unanimity is not needed.","A simple majority is for ordinary resolutions.",""],"x":1},{"u":"Unit 4","t":"Motion & Resolution","n":228,"q":"A proposal that has been moved but not yet put to the vote is called a","o":["proxy","casting vote","motion","quorum"],"a":2,"e":"A proposal moved but not voted yet is a motion.","g":1,"w":["Proxy is a representative.","A casting vote is the Chairman's tie-break.","","Quorum is attendance."]},{"u":"Unit 4","t":"Motion & Resolution","n":229,"q":"A resolution passed by directors through circulated papers without a meeting is a","o":["special resolution","proxy resolution","resolution by circulation","poll resolution"],"a":2,"e":"Passing by circulated papers is resolution by circulation.","g":1,"w":["A special resolution needs 75% at a meeting.","There is no proxy resolution.","","Poll is a counting method."]},{"u":"Unit 4","t":"Minutes","n":230,"q":"As per the secretarial standards, signed minutes of a Board meeting should be entered in the minutes book within","o":["1 day of the meeting, without the signature of the chairman","1 year of the meeting, after the audit of the accounts","5 years of the meeting, along with the annual return","30 days of the meeting"],"a":3,"e":"Signed minutes must be entered in the minutes book within 30 days.","g":1,"w":["1 day without signature is invalid.","1 year is too late.","5 years is too late.",""],"x":1},{"u":"Unit 4","t":"Minutes","n":231,"q":"Minutes are written in","o":["an informal style with the slang used by the members","the past tense and in a concise and impartial manner","the first person with a word for word record of all speeches","the future tense with the personal opinions of the secretary"],"a":1,"e":"Minutes are in the past tense, concise and impartial.","g":1,"w":["They are formal, not slang.","","They are not word-for-word.","Not in the future tense and not opinions."],"x":1},{"u":"Unit 4","t":"Minutes","n":232,"q":"Minutes of a meeting, once signed by the Chairman, are","o":["invalid until they are approved by the court of law","private opinions of the chairman, not binding on the company","a draft which can be changed by any member at any time","prima facie evidence of the proceedings"],"a":3,"e":"Signed minutes are prima facie evidence of what happened.","g":1,"w":["No court approval is needed.","They are the company's record, not private views.","Signed minutes are not a changeable draft.",""],"x":1},{"u":"Unit 4","t":"Meeting Documentation","n":233,"q":"The attendance register of a Board meeting is signed by","o":["the shareholders who are not directors of the company","directors present at the meeting","customers who have business dealings with the company","the auditor and the public who observe the meeting"],"a":1,"e":"Directors who attend sign the attendance register.","g":1,"w":["Outside shareholders do not attend.","","Customers do not attend Board meetings.","The auditor and public do not sign."],"x":1},{"u":"Unit 4","t":"Meeting Documentation","n":234,"q":"Who prepares the agenda of a Board meeting in consultation with the Chairman?","o":["Company Secretary","The peon of the company","The statutory auditor of the company","The bank manager of the company"],"a":0,"e":"The Company Secretary prepares the agenda with the Chairman.","g":1,"w":["","The peon does not.","The auditor does not.","The bank manager does not."],"x":1},{"u":"Unit 4","t":"Agenda","n":235,"q":"A statement explaining the nature of special business is attached to the notice as an","o":["balance sheet","audit report","directors' report","explanatory statement"],"a":3,"e":"An explanatory statement describes the special business (Section 102).","g":1,"w":["The balance sheet is financial.","The audit report is about accounts.","The directors' report is about the year.",""],"x":1}]
};
